ext('c10_sst_ch13',[
C("🗳️","चुनौतियाँ क्यों आती हैं",["व्यवस्था विकासशील है","आर्थिक और सामाजिक असमानता","शिक्षा और जागरूकता की कमी","मुद्दों का बदलना"],"लोकतंत्र कोई तैयार चीज़ नहीं, बल्कि लगातार विकसित होती व्यवस्था है। इसमें समय के साथ नई चुनौतियाँ आती हैं। समाज में आर्थिक और सामाजिक असमानता, शिक्षा की कमी और जागरूकता के अभाव से लोकतंत्र की गुणवत्ता प्रभावित होती है। जब लोग अपने अधिकारों और कर्तव्यों से अनजान होते हैं, तब वे सही फ़ैसले नहीं ले पाते। इसलिए चुनौतियों को पहचानना और उनका हल ढूँढना हर नागरिक का काम है।"),
Q("लोकतंत्र की चुनौती का अर्थ क्या है?","ऐसी कठिनाई जिसे दूर करके लोकतंत्र को और मज़बूत बनाया जा सकता है","अर्थ सोचिए... चुनौती वह बाधा है जो लोकतंत्र के बेहतर काम करने में रुकावट डालती है। उसका समाधान मिलने पर लोकतंत्र और मज़बूत होता है।"),
C("🧱","तीन बड़ी चुनौतियाँ",["बुनियाद की चुनौती","विस्तार की चुनौती","गहराई की चुनौती","हर देश में अलग रूप"],"दुनिया भर के लोकतंत्रों के सामने तीन तरह की चुनौतियाँ हैं। बुनियाद की चुनौती उन देशों के लिए है जहाँ अब भी लोकतंत्र नहीं है और उसकी नींव रखनी है। विस्तार की चुनौती का अर्थ है कि लोकतंत्र के बुनियादी सिद्धांत सभी स्तरों और समूहों तक पहुँचें। गहराई की चुनौती का अर्थ है कि संस्थाओं में लोगों की भागीदारी बढ़े और धन तथा ताक़त का अनुचित प्रभाव घटे। भारत में मुख्यतः विस्तार और गहराई की चुनौतियाँ हैं।"),
Q("विस्तार की चुनौती का एक उदाहरण दीजिए।","स्थानीय संस्थाओं तक अधिकार पहुँचाना, या महिलाओं और वंचितों को समान प्रतिनिधित्व","उदाहरण सोचिए... पंचायतों को अधिकार देना और महिलाओं को बराबर प्रतिनिधित्व देना लोकतंत्र के सिद्धांत को समाज के सभी वर्गों तक फैलाना है।"),
C("🇮🇳","भारत की प्रमुख चुनौतियाँ",["जातिवाद और साम्प्रदायिकता","भ्रष्टाचार","चुनाव में धन और बाहुबल","ग़रीबी और अशिक्षा"],"भारतीय लोकतंत्र की कई चुनौतियाँ हैं। कुछ लोग जाति या धर्म के आधार पर वोट देते हैं, जिससे असली मुद्दे पीछे रह जाते हैं। भ्रष्टाचार आम लोगों का सरकारी व्यवस्था पर भरोसा घटाता है। चुनावों में धन और बाहुबल का प्रभाव निष्पक्ष चुनाव को कमज़ोर करता है। ग़रीबी और अशिक्षा के कारण बहुत से लोग अपने अधिकारों का पूरा उपयोग नहीं कर पाते। अपराधी पृष्ठभूमि वाले उम्मीदवारों का मुद्दा भी चर्चा में रहता है।"),
Q("जाति के आधार पर वोट देना लोकतंत्र के लिए हानिकारक क्यों है?","क्योंकि इससे उम्मीदवार की योग्यता और असली मुद्दे दब जाते हैं और समाज में विभाजन बढ़ता है","कारण सोचिए... जब वोट जाति देखकर दिया जाता है तो योग्य और ईमानदार उम्मीदवार पीछे रह जाते हैं। साथ ही समाज में दूरियाँ बढ़ती हैं।"),
C("🛠️","राजनीतिक सुधार: कुछ सुझाव",["दलबदल पर रोक","चुनाव आयोग की भूमिका","सूचना का अधिकार","उम्मीदवार का शपथ पत्र"],"लोकतंत्र की चुनौतियाँ घटाने के लिए कई सुधार किए गए हैं। दलबदल को रोकने के लिए क़ानून बनाया गया है। चुनाव आयोग चुनाव निष्पक्ष कराने की व्यवस्था करता है। सूचना का अधिकार नागरिक को सरकारी कामकाज की जानकारी देता है। उम्मीदवारों को अपनी संपत्ति, शिक्षा और आपराधिक मामलों की जानकारी शपथ पत्र में देनी होती है। इन सुधारों से पारदर्शिता बढ़ी है, पर सुधार लगातार जारी रहना चाहिए।"),
Q("सूचना का अधिकार नागरिकों को क्या शक्ति देता है?","सरकारी विभागों से जानकारी माँगने की शक्ति, जिससे पारदर्शिता और जवाबदेही बढ़ती है","शक्ति सोचिए... कोई भी नागरिक किसी सरकारी काम का ब्योरा माँग सकता है। इससे भ्रष्टाचार घटता है और सरकार जवाबदेह बनती है।"),
C("👥","सुधार कौन करेगा",["जागरूक नागरिक","राजनीतिक दल","मीडिया और संगठन","विद्यार्थी और युवा"],"सुधार केवल क़ानून से नहीं होते, उनमें लोगों की भागीदारी ज़रूरी है। जागरूक नागरिक चुनाव में सोच-समझकर वोट देते हैं। राजनीतिक दलों को आंतरिक लोकतंत्र अपनाना चाहिए। मीडिया और सामाजिक संगठन ग़लत कामों को उजागर करते हैं। युवा और विद्यार्थी सवाल पूछकर और जागरूकता फैलाकर बदलाव ला सकते हैं। जब सब मिलकर काम करते हैं तभी लोकतंत्र सशक्त होता है।"),
Q("एक अच्छा मतदाता किन बातों का ध्यान रखता है?","उम्मीदवार का काम और योग्यता, जाति-धर्म से ऊपर उठकर वोट देना, लालच में न आना","बातें सोचिए... अच्छा मतदाता जानकारी जुटाकर वोट देता है, किसी लालच या दबाव में नहीं आता, और अपने क्षेत्र के विकास को ध्यान में रखता है।"),
C("🏘️","पंचायत और बिहार का लोकतंत्र",["पंचायत चुनाव","महिलाओं को आरक्षण","ग्राम सभा की भूमिका","स्थानीय स्तर पर भागीदारी"],"बिहार में पंचायतों में महिलाओं को पचास प्रतिशत आरक्षण मिला है, जिससे बड़ी संख्या में महिलाएँ मुखिया और वार्ड सदस्य बनी हैं। ग्राम सभा में सभी वयस्क लोग गाँव की योजनाओं पर चर्चा करते हैं। जब लोग अपनी पंचायत और ग्राम सभा में सक्रिय होते हैं, तो विकास योजनाएँ उनकी ज़रूरत के अनुसार बनती हैं। इसीलिए स्थानीय स्तर पर भागीदारी लोकतंत्र को गहराई देती है।"),
C("✍️","परीक्षा के लिए सुझाव",["चुनौतियों की सूची","सुधारों के उदाहरण","सुधार कौन करेगा","अपने उदाहरण"],"इस अध्याय में तीन चुनौतियों के नाम और अर्थ, भारत की मुख्य चुनौतियाँ और सुधारों के उदाहरण महत्वपूर्ण हैं। उत्तर में एक-एक उदाहरण जोड़िए, जैसे पंचायत में महिलाओं का आरक्षण। अंत में लिखिए कि जागरूक नागरिकों की भागीदारी से ही लोकतंत्र की चुनौतियों का समाधान संभव है। साफ़ बिंदु और सरल भाषा से उत्तर अच्छा बनता है।"),
],7)
